//! The PAC script the system proxy can point at instead of a fixed server.
//!
//! Windows has two ways to route traffic through us: `ProxyServer` (one address
//! for everything, plus a `ProxyOverride` list) and `AutoConfigURL` (a script
//! the browser runs per URL). The script is strictly more expressive, but it is
//! also *our* code running inside every application that reads it, so it must be
//! small, ASCII-only and impossible to get subtly wrong:
//!
//! 1. the generated file is pure ASCII — non-ASCII characters are written as
//!    `\uXXXX` escapes, because WinINet reads `.pac` as ANSI and a Chinese
//!    domain keyword would otherwise arrive mangled;
//! 2. every value is embedded through one escaper ([`js_string`]), so a domain
//!    containing `'` or `\` cannot break out of the literal;
//! 3. routing rules only contribute their *domain* matchers — IP ranges,
//!    geosite and process rules have no PAC equivalent, and pretending otherwise
//!    would silently send that traffic through the proxy;
//! 4. loopback, private and link-local names are always direct, independent of
//!    the user-editable bypass list: the proxy itself listens on 127.0.0.1, so
//!    proxying that would be a loop.

use std::path::Path;

use crate::domain::routing::{RuleAction, RuleMatcher, RoutingRule};

/// Render a PAC script that sends everything except the bypass and direct
/// domains to `127.0.0.1:port`.
///
/// `bypass` is the same semicolon list the settings page edits (see
/// [`crate::sysproxy::DEFAULT_BYPASS`]); `direct` is what
/// [`direct_patterns`] extracted from the routing table.
pub fn render(port: u16, bypass: &str, direct: &[String]) -> String {
    let (bypass_exact, bypass_wildcard, local_names) = split_bypass(bypass);
    let mut direct_exact = Vec::new();
    let mut direct_suffix = Vec::new();
    let mut direct_wildcard = Vec::new();
    for pattern in direct {
        if let Some(suffix) = pattern.strip_prefix('.') {
            direct_suffix.push(suffix.to_string());
        } else if pattern.contains('*') {
            direct_wildcard.push(pattern.clone());
        } else if !pattern.is_empty() {
            direct_exact.push(pattern.clone());
        }
    }

    let mut out = String::new();
    out.push_str("// Generated by X-Matrix Client Pro. Rewritten on every start; do not edit.\n");
    out.push_str(&format!(
        "var PROXY = {};\n",
        js_string(&format!("PROXY 127.0.0.1:{port}; DIRECT"))
    ));
    out.push_str(&format!(
        "var BYPASS_LOCAL_NAMES = {};\n",
        if local_names { "true" } else { "false" }
    ));
    out.push_str(&format!(
        "var BYPASS_EXACT = {};\n",
        js_array(&bypass_exact)
    ));
    out.push_str(&format!(
        "var BYPASS_WILDCARD = {};\n",
        js_array(&bypass_wildcard)
    ));
    out.push_str(&format!("var DIRECT_EXACT = {};\n", js_array(&direct_exact)));
    out.push_str(&format!(
        "var DIRECT_SUFFIX = {};\n",
        js_array(&direct_suffix)
    ));
    out.push_str(&format!(
        "var DIRECT_WILDCARD = {};\n",
        js_array(&direct_wildcard)
    ));
    out.push_str(SCRIPT);
    out
}

/// The fixed half of the script. Kept as a constant so the generated file has
/// no formatting logic of its own.
const SCRIPT: &str = r#"
function FindProxyForURL(url, host) {
  host = host.toLowerCase();
  if (isAlwaysDirect(host)) {
    return 'DIRECT';
  }
  if (isBypassed(host)) {
    return 'DIRECT';
  }
  if (isDirect(host)) {
    return 'DIRECT';
  }
  return PROXY;
}

// Loopback, private and link-local addresses never go through the proxy, no
// matter what the bypass list says. Two reasons: the proxy itself lives on
// 127.0.0.1, so sending that to it is a loop; and a LAN address is reachable
// only from this machine, so tunnelling it through the exit node can only fail.
// The fixed-proxy path gets this from WinINet's own <local> handling; a script
// has to say it itself, and the bypass field is user-editable, so it cannot be
// the only guard.
function isAlwaysDirect(host) {
  if (host === 'localhost') {
    return true;
  }
  if (host.indexOf(':') >= 0) {
    // IPv6 arrives in brackets for a URL host but not always.
    if (host === '[::1]' || host === '::1') {
      return true;
    }
    if (host.indexOf('[fe80') === 0 || host.indexOf('fe80') === 0) {
      return true;
    }
    if (host.indexOf('[fc') === 0 || host.indexOf('fc') === 0) {
      return true;
    }
    if (host.indexOf('[fd') === 0 || host.indexOf('fd') === 0) {
      return true;
    }
    return false;
  }
  if (host.indexOf('.') < 0) {
    // A plain name is a LAN name, the same thing <local> means.
    return true;
  }
  if (host.indexOf('127.') === 0 || host.indexOf('10.') === 0) {
    return true;
  }
  if (host.indexOf('192.168.') === 0 || host.indexOf('169.254.') === 0) {
    return true;
  }
  if (host.indexOf('172.') === 0) {
    var second = parseInt(host.split('.')[1], 10);
    if (second >= 16 && second <= 31) {
      return true;
    }
  }
  // Manual suffix test rather than dnsDomainIs: this runs before any host
  // function the engine may or may not provide.
  return host.length >= 6 && host.substring(host.length - 6) === '.local';
}

function isBypassed(host) {
  if (BYPASS_LOCAL_NAMES && host.indexOf('.') < 0) {
    return true;
  }
  // A plain loop, not `Array.prototype.indexOf`: WinINet runs this script in
  // JScript 5.8, which has no ES5 array methods. An exception there is silently
  // treated as "direct", i.e. the whole machine would bypass us.
  for (var e = 0; e < BYPASS_EXACT.length; e++) {
    if (host === BYPASS_EXACT[e]) {
      return true;
    }
  }
  for (var i = 0; i < BYPASS_WILDCARD.length; i++) {
    if (shExpMatch(host, BYPASS_WILDCARD[i])) {
      return true;
    }
  }
  return false;
}

function isDirect(host) {
  for (var i = 0; i < DIRECT_EXACT.length; i++) {
    if (host === DIRECT_EXACT[i]) {
      return true;
    }
  }
  for (var j = 0; j < DIRECT_SUFFIX.length; j++) {
    if (host === DIRECT_SUFFIX[j] || dnsDomainIs(host, '.' + DIRECT_SUFFIX[j])) {
      return true;
    }
  }
  for (var k = 0; k < DIRECT_WILDCARD.length; k++) {
    if (shExpMatch(host, DIRECT_WILDCARD[k])) {
      return true;
    }
  }
  return false;
}
"#;

/// Turn the routing table into the domain patterns the PAC script can honour.
///
/// Only enabled rules whose action is `Direct` contribute, and only their domain
/// matchers: `DomainFull` becomes an exact name, `DomainSuffix` keeps its
/// leading dot, `DomainKeyword` becomes a `*keyword*` glob. Everything else
/// (IP ranges, geosite, process, regex) is dropped — see the module docs.
///
/// Sorted and de-duplicated so the generated file is stable: a needless rewrite
/// would make the browser reload the script for nothing.
pub fn direct_patterns(rules: &[RoutingRule]) -> Vec<String> {
    let mut patterns = Vec::new();
    for rule in rules {
        if !rule.enabled || rule.action != RuleAction::Direct {
            continue;
        }
        let pattern = match &rule.matcher {
            RuleMatcher::DomainFull { value } => Some(value.trim().to_lowercase()),
            RuleMatcher::DomainSuffix { value } => {
                let value = value.trim().trim_start_matches('.').to_lowercase();
                Some(format!(".{value}"))
            }
            RuleMatcher::DomainKeyword { value } => {
                let value = value.trim().to_lowercase();
                Some(format!("*{value}*"))
            }
            _ => None,
        };
        if let Some(pattern) = pattern
            && !pattern.trim_matches(&['.', '*'][..]).is_empty()
        {
            patterns.push(pattern);
        }
    }
    patterns.sort();
    patterns.dedup();
    patterns
}

/// `file:///C:/.../x-matrix.pac` for a Windows path.
///
/// Browsers require the URL form in `AutoConfigURL`, not a path: the value is
/// read by WinINet and fed straight to `FindProxyForURL` without a shell to
/// resolve it. Spaces and non-ASCII bytes are percent-encoded as UTF-8, which is
/// what the URL parser expects.
pub fn file_url(path: &Path) -> String {
    let raw = path.to_string_lossy().replace('\\', "/");
    let mut out = String::from("file:///");
    // A drive letter is already absolute; a leading slash would make it
    // `file:////C:` and the parser would not see a drive at all.
    for ch in raw.trim_start_matches('/').chars() {
        if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '.' | '_' | '~' | ':' | '/') {
            out.push(ch);
        } else {
            let mut buffer = [0u8; 4];
            for byte in ch.encode_utf8(&mut buffer).as_bytes() {
                out.push_str(&format!("%{byte:02X}"));
            }
        }
    }
    out
}

/// Split a semicolon bypass list into exact names, `shExpMatch` globs, and the
/// `<local>` flag.
///
/// The exact list also drops names that cannot match: an entry without a dot is
/// still a valid host, so it stays. Entries with a `*` go to the glob list
/// instead, or `10.*` would be compared literally.
fn split_bypass(bypass: &str) -> (Vec<String>, Vec<String>, bool) {
    let mut exact = Vec::new();
    let mut wildcard = Vec::new();
    let mut local = false;
    for entry in bypass.split(';') {
        let entry = entry.trim();
        if entry.is_empty() {
            continue;
        }
        if entry.eq_ignore_ascii_case("<local>") {
            local = true;
        } else if entry.contains('*') {
            wildcard.push(entry.to_lowercase());
        } else {
            exact.push(entry.to_lowercase());
        }
    }
    exact.sort();
    exact.dedup();
    wildcard.sort();
    wildcard.dedup();
    (exact, wildcard, local)
}

/// A JavaScript single-quoted literal, ASCII-only.
///
/// Everything outside printable ASCII becomes `\uXXXX`, so the file is valid no
/// matter which code page WinINet uses; `'`, `\` and newlines are escaped so a
/// domain cannot terminate the literal.
fn js_string(value: &str) -> String {
    let mut out = String::from("'");
    for ch in value.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '\'' => out.push_str("\\'"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            ' '..='~' => out.push(ch),
            _ => {
                let mut units = [0u16; 2];
                for unit in ch.encode_utf16(&mut units) {
                    out.push_str(&format!("\\u{unit:04X}"));
                }
            }
        }
    }
    out.push('\'');
    out
}

fn js_array(items: &[String]) -> String {
    if items.is_empty() {
        return "[]".to_string();
    }
    let body: Vec<String> = items.iter().map(|item| js_string(item)).collect();
    format!("[{}]", body.join(", "))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rule(id: &str, enabled: bool, matcher: RuleMatcher, action: RuleAction) -> RoutingRule {
        RoutingRule {
            id: id.into(),
            name: id.into(),
            enabled,
            matcher,
            action,
        }
    }

    #[test]
    fn the_script_points_at_the_given_port() {
        let script = render(7890, "localhost;127.*", &[]);
        assert!(script.contains("PROXY 127.0.0.1:7890; DIRECT"), "{script}");
        assert!(script.contains("function FindProxyForURL(url, host)"));
    }

    #[test]
    fn the_bypass_list_is_split_into_exact_and_glob_entries() {
        let script = render(7890, "localhost;10.*;<local>", &[]);
        assert!(script.contains("BYPASS_EXACT = ['localhost']"), "{script}");
        assert!(script.contains("BYPASS_WILDCARD = ['10.*']"), "{script}");
        assert!(script.contains("BYPASS_LOCAL_NAMES = true"), "{script}");
    }

    #[test]
    fn stray_separators_and_case_do_not_create_empty_patterns() {
        let script = render(7890, " localhost ;; LOCALHOST ;<LOCAL>; *.Corp.Example ", &[]);
        assert!(script.contains("BYPASS_EXACT = ['localhost']"), "{script}");
        assert!(script.contains("BYPASS_WILDCARD = ['*.corp.example']"), "{script}");
        assert!(script.contains("BYPASS_LOCAL_NAMES = true"), "{script}");
    }

    #[test]
    fn an_empty_bypass_list_leaves_the_script_valid() {
        let script = render(7890, "  ", &[]);
        assert!(script.contains("BYPASS_EXACT = []"), "{script}");
        assert!(script.contains("BYPASS_LOCAL_NAMES = false"), "{script}");
    }

    #[test]
    fn loopback_and_private_names_are_direct_without_any_bypass_entry() {
        // The bypass field is user-editable and arrives from a store that may be
        // stale or hand-edited; the loopback guard must not depend on it.
        let script = render(7890, "", &[]);
        assert!(script.contains("function isAlwaysDirect"), "{script}");
        assert!(script.contains("if (isAlwaysDirect(host))"), "{script}");
        assert!(script.contains("BYPASS_LOCAL_NAMES = false"), "{script}");
        assert!(script.is_ascii());
    }

    #[test]
    fn direct_patterns_only_come_from_enabled_direct_domain_rules() {
        let rules = vec![
            rule(
                "full",
                true,
                RuleMatcher::DomainFull {
                    value: "Example.COM".into(),
                },
                RuleAction::Direct,
            ),
            rule(
                "suffix",
                true,
                RuleMatcher::DomainSuffix {
                    value: ".Corp.Example".into(),
                },
                RuleAction::Direct,
            ),
            rule(
                "keyword",
                true,
                RuleMatcher::DomainKeyword {
                    value: "Google".into(),
                },
                RuleAction::Direct,
            ),
            rule(
                "disabled",
                false,
                RuleMatcher::DomainFull {
                    value: "off.example".into(),
                },
                RuleAction::Direct,
            ),
            rule(
                "proxied",
                true,
                RuleMatcher::DomainFull {
                    value: "proxied.example".into(),
                },
                RuleAction::Proxy,
            ),
            rule(
                "ip",
                true,
                RuleMatcher::IpCidr {
                    value: "10.0.0.0/8".into(),
                },
                RuleAction::Direct,
            ),
        ];

        assert_eq!(
            direct_patterns(&rules),
            vec![
                "*google*".to_string(),
                ".corp.example".to_string(),
                "example.com".to_string(),
            ]
        );
    }

    #[test]
    fn direct_patterns_ignore_blank_values() {
        let rules = vec![rule(
            "blank",
            true,
            RuleMatcher::DomainSuffix {
                value: " . ".into(),
            },
            RuleAction::Direct,
        )];
        assert!(direct_patterns(&rules).is_empty());
    }

    #[test]
    fn the_script_classifies_direct_patterns_by_shape() {
        let script = render(
            7890,
            "",
            &[
                "example.com".to_string(),
                ".corp.example".to_string(),
                "*ads*".to_string(),
            ],
        );
        assert!(script.contains("DIRECT_EXACT = ['example.com']"), "{script}");
        assert!(script.contains("DIRECT_SUFFIX = ['corp.example']"), "{script}");
        assert!(script.contains("DIRECT_WILDCARD = ['*ads*']"), "{script}");
    }

    #[test]
    fn a_quote_in_a_domain_cannot_break_the_literal() {
        let script = render(7890, "it's;back\\slash", &["*o'neil*".to_string()]);
        assert!(script.contains(r"'it\'s'"), "{script}");
        assert!(script.contains(r"'back\\slash'"), "{script}");
        assert!(script.contains(r"'*o\'neil*'"), "{script}");
    }

    #[test]
    fn non_ascii_is_escaped_so_the_file_can_be_any_encoding() {
        // WinINet reads a PAC as ANSI, so a literal Chinese keyword would arrive
        // as mojibake; an escape sequence survives every code page.
        let script = render(7890, "", &["*中文*".to_string()]);
        assert!(script.contains(r"\u4E2D\u6587"), "{script}");
        assert!(script.is_ascii(), "the generated script must be pure ASCII");
    }

    #[test]
    fn file_url_uses_the_url_form_of_a_windows_path() {
        let url = file_url(Path::new(r"D:\Users\Some One\AppData\x-matrix.pac"));
        assert_eq!(url, "file:///D:/Users/Some%20One/AppData/x-matrix.pac");
    }

    #[test]
    fn file_url_encodes_non_ascii_as_utf8() {
        let url = file_url(Path::new(r"C:\临时\x.pac"));
        assert_eq!(url, "file:///C:/%E4%B8%B4%E6%97%B6/x.pac");
    }
}
